import{_ as p,c as e,o as r,af as h}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"困","description":"高岛易断 - 困","frontmatter":{"title":"困","description":"高岛易断 - 困"},"headers":[],"relativePath":"zh/classics/takashima/047.md","filePath":"zh/classics/takashima/047.md"}'),i={name:"zh/classics/takashima/047.md"};function l(n,a,d,t,s,c){return r(),e("div",null,[...a[0]||(a[0]=[h('<h1 id="困" tabindex="-1">困 <a class="header-anchor" href="#困" aria-label="Permalink to “困”">​</a></h1><h2 id="困-1" tabindex="-1">困 <a class="header-anchor" href="#困-1" aria-label="Permalink to “困”">​</a></h2><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>困：亨，贞。大人吉，无咎。有言不信。</p><h2 id="卦辞注" tabindex="-1">卦辞注 <a class="header-anchor" href="#卦辞注" aria-label="Permalink to “卦辞注”">​</a></h2><p>“困”字，从木，在口中。木为阳之生气，历《坎》地则凋，逢《兑》金则刑，木斯困矣。必自《兑》而《坎》，转而入《震》，《震》为春，为生，则木道乃亨。古来贤哲，其蒙难艰贞，不知几经困苦，而始得亨通者，类如斯矣，故曰“大人吉，无咎”。“有言不信”者，谓当此困厄之际，身既不用，言何足重？惟宜简默隐忍，以道自守，若复喋喋多言，反足招尤，其谁听信乎！</p><h2 id="象辞" tabindex="-1">象辞 <a class="header-anchor" href="#象辞" aria-label="Permalink to “象辞”">​</a></h2><p>泽无水，困。君子以致命遂志。</p><h2 id="象辞注" tabindex="-1">象辞注 <a class="header-anchor" href="#象辞注" aria-label="Permalink to “象辞注”">​</a></h2><p>《井》《象》谓“木上有水”，取其可汲养也；《师》《象》谓“地中有水”，取其能容畜也；《困》之《象》曰“泽无水”，无水则无可汲养，亦无所容畜，而泽困矣。《坎》为水，亦为志，君子观之，谓泽之不得水，犹士之不得志也。孔子曰，得之不得曰有命，命当其困，身可困，志不可夺也。譬如危城孤守，强敌环攻，内兵疲而外援绝，矢穷力尽，一战身亡，以遂靖共之忠，斯不失见危授命之义也，是之谓“君子以致命遂志”。盖命在天，志在我，时当困穷已极，无可奈何；命则听之于天，志则尽夫在我，为道谋不为身谋，计百年不计一日。“困而不失其所亨”，惟君子能之。</p><h2 id="占断" tabindex="-1">占断 <a class="header-anchor" href="#占断" aria-label="Permalink to “占断”">​</a></h2><p>○　问时运：困穷至此，宜自安命。</p><p>○　问战征：是为孤城危急之时，惟竭力图存，生死在所不计也。</p><p>○　问功名：名成则身难保，身存则名恐败，惟善自处之。</p><p>○　问营商：资财既竭，时事又危，爻取往凶来吉，不如归来，得可免困。</p><p>○　问婚姻：《彖》曰“刚揜”，男必夭命，女必守寡。易位为节，女必能守节成名。</p><p>○　问家宅：宅中有枯井，防致损命。</p><p>○　问讼事：不特讼不能直，且防因讼损命。</p><p>○　问行人：在外困苦不堪，且有生命之忧。</p><p>○　问疾病：肾水亏弱，症象已危。</p><p>○　问失物：坠入深潭之下，不可复得。</p><p>○　问六甲：生男。</p><h2 id="初六解" tabindex="-1">初六解 <a class="header-anchor" href="#初六解" aria-label="Permalink to “初六解”">​</a></h2><p>《坎》为臀，初处内卦之下，臀在人身之下，取《坎》下之象。《象传》曰“泽无水”，为漏泽，臀之象亦漏下。《坎》于木为坚多心，“株木”为根在土上者，最在低下。人以臀为下，木以株为下，故为“臀困于株木”。凡人间居失业，谓之株守，可以为证。《兑》为谷，为幽，《坎》为入，为穴，为陷，阴爻亦为穴，“入于幽谷”，是陷《坎》之底。《兑》为见，《坎》为三岁，《坎》伏《兑》下，自初至四，历三爻而《兑》始见，故曰“入于幽谷，三岁不觌”，皆从《坎》为隐伏取象。《象传》以“幽不明”释之，“幽”，暗也，人当困厄之来，宜审机度势，择地而蹈，冀可免厄。“困于株木，入于幽谷”，是困上加困也，亦因其不明所致也耳。</p><h2 id="初六占" tabindex="-1">初六占 <a class="header-anchor" href="#初六占" aria-label="Permalink to “初六占”">​</a></h2><p>○　问时运：厄运初来，渐入苦境，三年后可望顺适。</p><p>○　问战征：兵陷险地，如司马氏军入葫芦谷。</p><p>○　问营商：是贩运材木生意，木在深谷，困于发运。</p><p>○　问功名：卑下之象，名必不显。</p><p>○　问家宅：宅在深山，人迹罕到，宜于幽人。</p><p>○　问疾病：“株木”“幽谷”，有棺椁山丘之象，凶。</p><p>○　问婚姻：男家卑微，恐有遇人不淑之叹。</p><p>○　问行人：三年后可归。</p><p>○　问六甲：生男。</p><h2 id="初六案例" tabindex="-1">初六案例 <a class="header-anchor" href="#初六案例" aria-label="Permalink to “初六案例”">​</a></h2><p>明治十九年七月，横滨友人某来，谓本年大孤兵库等处，虎列喇疫病流行，幸东京横滨皆得无恙，不料本月横滨花町忽有一人患此症，尔来仆居邻近，亦有传染。深为忧虑，请为一筮，以决吉凶。筮得《困》之《兑》。</p><p>断曰：《坎》为疾，为灾，显见有病。卦名曰《困》，《困》者难也。卦象“泽无水”，泽在水上，水必下漏，臀为孔，是必泄泻之症。《兑》为秋，《坎》为冬，病起于秋，延及于冬，是时疫也。今占初爻，爻辞曰“臀困于株木”，象近棺木，“入于幽谷”，象近葬穴，爻象颇凶；幸在初爻，病在初发，《彖传》曰“困亨”，明示《困》之中，自有得亨之道也。“入于幽谷”，其殆示以避疫之地也；“幽谷”者，必是深山幽僻之所；“三岁不觌”者，自初至四，凡历三爻，四爻入《兑》，《兑》为悦，为见，至《兑》则灾脱，而心悦，可以出而相见也。三者为数之一变，暂则三岁，久则三月，皆取三也。玩此占辞，君宜暂避于函根、伊香保等处，自可无患。某氏闻之大惊，即日起行，赴伊香保，果得平安无灾。</p><h2 id="九二解" tabindex="-1">九二解 <a class="header-anchor" href="#九二解" aria-label="Permalink to “九二解”">​</a></h2><p>三、四、五三爻为刚，皆困于富贵者也。二与五应，二所云服饰祭享，与五爻同，五虽未言“酒食”，有祭享必有酒食，义亦可通。《坎》五曰“樽酒簋贰”，故有酒食象。《困》三阴三阳，卦自《乾》《坤》来，《乾》为衣，亦为朱，《坤》为裳，故有朱绂象。二动体为《萃》，《萃》二曰“利用禴”，故有享祀象。按：绂，蔽膝祭服；一作韨，《玉藻》曰：“一命组韨幽衡，再命赤韨幽衡，三命朱绂葱衡。”二为大夫，故祭服用朱绂。二得乾气，方膺大夫之命，故曰“方来”。“酒食”“朱绂”，谓膏梁足以伤生，文绣因而溺志，富贵之困人，即所谓死于安乐者是也。君子知之，不以酒食自养，不以朱绂自耀，而用诸祭祀，则俎豆馨香，孝孙有庆矣。“征凶”者，以斯而征，坎险在前，为三所阻，故“凶”；幸二居《坎》之中，故得“无咎”，是以《彖传》即以“中有庆”释之。</p><h2 id="九二占" tabindex="-1">九二占 <a class="header-anchor" href="#九二占" aria-label="Permalink to “九二占”">​</a></h2><p>○　问时运：爻象富贵，运非不佳，惜其不知撙节，反为富贵所困也。</p><p>○　问战征：防有因酒食误事，遂致败北，主将困而招褫绯之辱。</p><p>○　问营商：因商起家，膏梁文绣，足以荣亨，但再往则有凶也。</p><p>○　问功名：功名已显，但恐为功名所困耳。</p><p>○　问疾病：是逸乐过甚，醉饱无度。宜祷。</p><p>○　问家宅：是富贵之家，住宅六神不安，宜虔祭告。无咎。</p><p>○　问婚姻：聘礼始备，彩礼方来，一说即成。</p><p>○　问六甲：生男。</p><h2 id="九二案例" tabindex="-1">九二案例 <a class="header-anchor" href="#九二案例" aria-label="Permalink to “九二案例”">​</a></h2><p>板垣伯占气运，得此爻，断词附载《地雷复》上爻，可以参看。</p><p>点击进入《地雷复》上爻</p><h2 id="六三解" tabindex="-1">六三解 <a class="header-anchor" href="#六三解" aria-label="Permalink to “六三解”">​</a></h2><p>初、三、上三爻为柔，皆困于患难者也。柔爻象取草木，三与上应，三曰“蒺藜”，上曰“葛藟”，其象相近。三居《坎》之极，互体为《艮》，《艮》为小石，《象传》谓“泽无水”，无水之地，泥土皆成砂碛，有石之象，故曰“困于石”。《坎》为蒺藜，蒺藜，草之有刺者也。军中有铁蒺藜，形似蒺藜，以铁为之，布之于地，使敌不能前进。三爻陷下，乘二之刚，欲进不能，欲退不得，有似“据于蒺藜”。《坎》为宫为入，《兑》为少女，有妻之象，亦为见。三动体为《大过》，二曰“女妻”，五曰“老妇”，三则曰“栋挠”，则宫崩矣。宫之中已阒无人，何有于“女妻”，何有于“老妇”？故曰，“入于其宫，不见其妻”。《系辞》谓“非所困而困，名必辱，非所据而据，身必危”，辱且危，故凶。《象传》以“乘刚”释据“蒺藜”，以三乘二之刚也，以“不祥”释入其宫；以不见妻为凶也。</p><h2 id="六三占" tabindex="-1">六三占 <a class="header-anchor" href="#六三占" aria-label="Permalink to “六三占”">​</a></h2><p>○　问时运：命运尴尬，进退两难，凶。</p><p>○　问战征：上布矢石，下设陷阱，前进则身多危，后退则膏已陷，大凶之象。</p><p>○　问功名：身将不保，奚以名为？</p><p>○　问营商：卜例，妻为财爻，宫即命宫，既丧其命，又失其财，大凶。</p><p>○　问疾病：《系辞》曰“死期将至”，知病不可救也。</p><p>○　问婚姻：防有悼亡之戚。</p><p>○　问失物：不得。</p><p>○　问讼事：必散。</p><p>○　问六甲：生男。</p><h2 id="六三案例" tabindex="-1">六三案例 <a class="header-anchor" href="#六三案例" aria-label="Permalink to “六三案例”">​</a></h2><p>明治十九年七月，余为避虎列喇时症，滞留函岭木贺温泉，东京物商藤田某，亦为避疫而来。止宿同馆，出东京来简示余曰：仆亲戚之妇某氏，忽罹时症，不知死生如何？敢请一占。筮得《困》之《大过》。</p><p>断曰：《系辞》谓《困》三“非所困而困，非所据而据”，“死期将至，妻其可得见耶”？已明示其凶矣，不待断而可知也。翌日得电报，此妇已死，计其时刻，昨当揲蓍之顷，适值入棺之候。三变为《大过》，《易》以《大过》为棺椁，其机更为灵妙。</p><h2 id="九四解" tabindex="-1">九四解 <a class="header-anchor" href="#九四解" aria-label="Permalink to “九四解”">​</a></h2><p>《兑》为金，《坎》为车，九四《震》爻，辰在卯，上值房，石氏曰“房主车驾”，故有金车之象。四与初应，故相往来。“徐徐”，舒迟之状；初居最下，四自外来，为二所间，疑惧不前，故曰“来徐徐”。四为诸侯，得乘金车，是亦乘刚而困于富贵者也。困于《坎》宫，困在身，困于富贵，困在心。四知初之困于柔，若不知已之困于刚也，乘此金车，徐徐来往，而不能以济困，车殆马烦，徒自苦耳，故“吝”。以阳居阴，为履不当位，然虽无二五之中，而自有二五之刚，惟刚足以自立，四得其刚，而二五复为推挽，庶几相与有成，岂至终“困于金车”哉！故曰“有终”。是以《象传》以“有与”释之。</p><h2 id="九四占" tabindex="-1">九四占 <a class="header-anchor" href="#九四占" aria-label="Permalink to “九四占”">​</a></h2><p>○　问时运：运非不好，但地位不当，致多疑惧，未免为人所鄙。</p><p>○　问战征：迟缓不进，以致车辙靡乱，幸得救援，不至终败。</p><p>○　问营商：办事不力，致运载货物，中途失陷，急救得全。</p><p>○　问功名：始困终亨。</p><p>○　问家宅：地位不当，为间分间隔，不能联合，待迟缓乃佳。</p><p>○　问婚姻：缓缓可成。</p><p>○　问疾病：病势迟缓，已非一日，想是驰驱劳顿致损。爻曰“有终”，其命永终矣。</p><p>○　问失物：想遗落车中，寻之可得。</p><p>○　问讼事：迁延已久，今始可罢。</p><p>○　问六甲：生女。</p><h2 id="九四案例" tabindex="-1">九四案例 <a class="header-anchor" href="#九四案例" aria-label="Permalink to “九四案例”">​</a></h2><p>友人某来，请占气运，筮得《困》之《坎》。</p><p>断曰：君所问在气运，而君意专在借货，以借货论。四下与初应，初爻柔为贫，四爻刚为富，当以初爻属君，四爻属货者。在四固有意于初，间为二爻所阻，致四迟疑，不克速允，四亦未免有吝。为今之计，二与五应，必须挽五与二说开，则不相阻而相助，斯借货终得许允也。后挽人向二说之，果得成就。</p><h2 id="九五解" tabindex="-1">九五解 <a class="header-anchor" href="#九五解" aria-label="Permalink to “九五解”">​</a></h2><p>《兑》为毁折，亦为刑人，劓截其鼻，刖断其足，古之所谓肉刑也。五居尊位，为《困》之主，是主刑者也。至治之朝，政简刑清，君民相得，不为无耻之幸免，而为有耻之且格，斯可谓之得志矣。若惟恃劓刖之用，自矜明察，上邀受服之荣，下蒙赭衣之苦，槛车毳衣，徒见其困而已，故“困于赤绂”，系诸“劓刖”之下也。《兑》为口，“乃徐有说，”弼教之道，以渐而入，故曰“徐”。知用刑之不得其志，则齐之以刑，不如道之以德，此为教化之渐；而仁义之流，非独肌肤之效也。道惟在于中直，中则无偏，直者无枉，以此中直而临民，即以此中直而事神，则服赤绂而荐馨香，而来亨来格，降尔遐福，斯困于人者，必不困于天矣，故曰“利用祭祀”。《象传》以“受福”释之，九五阳爻属《乾》，《乾》为福，福自《乾》来，既所谓自天受之也。</p><h2 id="九五占" tabindex="-1">九五占 <a class="header-anchor" href="#九五占" aria-label="Permalink to “九五占”">​</a></h2><p>○　问时运：命运刚强，刚则必折，防有损伤。作事宜筹度舒迟，乃可变祸为福。</p><p>○　问营商：货物底面，防有溃烂损伤，须拆看收拾，徐徐出售，无咎。</p><p>○　问功名：防富贵后，致有刑伤，宜祷。</p><p>○　问战征：主败，须徐缓收兵，可图后胜。</p><p>○　问家宅：家业却好，主家人有烂鼻跛足之患，宜祈祷。</p><p>○　问疾病：病在头足，徐徐调养，求神医治，可愈。</p><p>○　问婚姻：主有残疾，始不合意，后得完好。</p><p>○　问讼事：防有刑狱之灾，须徐徐辩白，方可免罢。</p><p>○　问行人：在外有灾，宜祷，后可得意而归。</p><p>○　问失物：必有破伤，久后可以寻获。</p><p>○　问六甲：生女。</p><h2 id="九五案例" tabindex="-1">九五案例 <a class="header-anchor" href="#九五案例" aria-label="Permalink to “九五案例”">​</a></h2><p>缙绅某来，请占气运，筮得《困》之《解》。</p><p>断曰：“劓”，谓截其鼻也，“刖”，谓断其足也。“困于赤绂”，谓富贵而受困也，“乃徐有说，利用祭祀”，谓舒缓开道，利用酒食以和解也。想足下于朋友之间，严厉过甚，令人面目无光，无可退步。今彼故与足下为难，于广众之地，乘足下文绣而来，大施残辱，是所谓“困于赤绂”也。足下须降心下气，徐徐辩说，或复置酒立盟，誓不复记旧恨，乃可转祸为福，否则冤冤相寻，无有已时也。足下占得《困》五爻，爻象如此，余就占而断，合与不合，足下当自知之。</p><h2 id="上六解" tabindex="-1">上六解 <a class="header-anchor" href="#上六解" aria-label="Permalink to “上六解”">​</a></h2><p>《兑》为附决，孔颖达曰，“附决为果瓜之属”，故有葛藟之象。上六居《兑》之极，与初三并为阴爻，故象取草木，是谓困于患难者也。上六去《坎》己远，似可出幽谷而迁乔木矣，乃重柔不中，不能自立，如葛藟之附物蔓延，摇宕不安，故臲卼。臲卼，不安之状；一作杌陧，文异而音义通也。欲脱此困，非动不可，然动则不能无悔，故曰“动悔”；惟知其动之有悔，而审慎以出之，正将因悔以求全，转以有悔而可往。盖道以穷而始达，境由苦而得甘，此迁善所以必先悔过也。由此以往，往无不吉，故曰“吉”。《象传》一则以“未当”释之，谓其为柔所困，柔“未当也”；一则以“吉行”释之，谓其以动得悔，悔亦吉也。</p><h2 id="上六占" tabindex="-1">上六占 <a class="header-anchor" href="#上六占" aria-label="Permalink to “上六占”">​</a></h2><p>○　问时运：目下苦运已终，本可脱难，缘其心神不安，未能立作变计，一旦改悔，即可获吉。</p><p>○　问功名：困穷既久，行将风云变动，一举成名。吉。</p><p>○　问营商：“困于葛藟”，必是包扎货物，久不得售，今当时价发动，即可获利。吉。</p><p>○　问战征：爻曰“征吉”，《象》曰“吉行”，其中虽有灾悔，定可因悔得吉也。</p><p>○　问疾病：此病必缠绵已久，神志不安，当迁地静养，自然痊愈。</p><p>○　问家宅：此宅已旧，藤葛丛生，栋柱倾斜，宜动工改作，乃吉。</p><p>○　问婚姻：其中防有瓜葛未清，看其动静如何，一动之后，斯可成就。吉。</p><p>○　问讼事：缠绕未休，致多臲卼，必待断结，乃可无事。</p><p>○　问行人：一时被事纠缠，难归。</p><p>○　问失物：被物绕住，不见，必移动后，乃可寻获。</p><p>○　问六甲：生女。</p><h2 id="上六案例" tabindex="-1">上六案例 <a class="header-anchor" href="#上六案例" aria-label="Permalink to “上六案例”">​</a></h2><p>友人某来，请占气运，筮得《困》之《讼》。</p><p>断曰：《大象》曰“泽无水”，无水则物不得滋养，而无以生发，犹人无财而无以生活，为困穷之甚也。今占得上爻，上爻《困》之终，本可脱困，《困》卦体柔弱过甚，如葛藟之施木，不能自立，以致飘荡不安，若能决然思奋，动而有为，故曰“征吉”。所谓“征吉”，利于出行，不利坐守。足下宜乎遵此断而行，后运正佳。</p>',116)])])}const m=p(i,[["render",l]]);export{b as __pageData,m as default};
